  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: The Thread of Promise: The Covenants$j$, $j${"questions": [{"q": "What is a covenant?", "options": ["A binding agreement in which God commits Himself to His people", "A list of kings", "A kind of poem", "A type of offering"]}, {"q": "Which covenant promised a land, a nation and a blessing to all families of the earth?", "options": ["The covenant at Sinai", "The covenant with Abraham", "The covenant with David", "The covenant with Noah"]}, {"q": "What did God promise David in 2 Samuel 7?", "options": ["A throne that would be established for ever", "A new temple of stone", "A new law", "A great flood"]}, {"q": "According to Luke 24:44, what did Jesus say about the law of Moses, the prophets and the psalms?", "options": ["They were no longer needed", "They belonged to the priests alone", "They were only history", "They were written concerning Him"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: The Thread of Promise: The Covenants$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,0,3}'::int[], array[$j$A covenant is a binding agreement with promises that God makes to His people.$j$,$j$God promised Abraham a land, a nation and a blessing for all families of the earth (Genesis 12:1 to 3).$j$,$j$God promised that David's house, kingdom and throne would last for ever.$j$,$j$Jesus said that all things written in the law, the prophets and the psalms concerned Him.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: The Thread of Promise: The Covenants$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Prophecies of the Messiah$j$, $j${"questions": [{"q": "What does the word Messiah mean?", "options": ["Priest of the temple", "Anointed one", "King of Egypt", "Teacher"]}, {"q": "What does Immanuel mean, according to Matthew 1:23?", "options": ["The mighty king", "God with us", "Prince of peace", "Son of David"]}, {"q": "Which town did Micah 5:2 name as the place the ruler would come from?", "options": ["Jericho", "Jerusalem", "Nazareth", "Bethlehem"]}, {"q": "Which chapter describes a servant who was wounded for our transgressions?", "options": ["Psalm 23", "Micah 6", "Genesis 22", "Isaiah 53"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Prophecies of the Messiah$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,3}'::int[], array[$j$Messiah means anointed one, and the Greek form is Christ.$j$,$j$Matthew 1:23 says Immanuel means God with us.$j$,$j$Micah named Bethlehem Ephratah.$j$,$j$Isaiah 53 describes the suffering servant.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Prophecies of the Messiah$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Sacrifice, Priesthood and the Prophet like Moses$j$, $j${"questions": [{"q": "What did Abraham tell Isaac that God would provide in Genesis 22:8?", "options": ["A fortress", "A lamb for a burnt offering", "A king", "A new land"]}, {"q": "According to Leviticus 17:11, why was blood used on the altar?", "options": ["The life of the flesh is in the blood, to make an atonement for the soul", "It made the altar clean", "It pleased the priests", "It was a symbol of war"]}, {"q": "What did Moses promise in Deuteronomy 18:15?", "options": ["That the temple would be taken away", "That the law would end", "That God would raise up a Prophet like Moses", "That Israel would have no more prophets"]}, {"q": "What did John the Baptist say when he saw Jesus?", "options": ["Behold the sign of Jonah", "Behold the temple of the LORD", "Behold the king of Babylon", "Behold the Lamb of God, which taketh away the sin of the world"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Sacrifice, Priesthood and the Prophet like Moses$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,3}'::int[], array[$j$Abraham said, God will provide himself a lamb for a burnt offering.$j$,$j$Blood made atonement for the soul because the life is in the blood.$j$,$j$Moses said God would raise up a Prophet like unto him.$j$,$j$John 1:29 records this declaration.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Sacrifice, Priesthood and the Prophet like Moses$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Between the Testaments and the Fullness of Time$j$, $j${"questions": [{"q": "About how many years passed between Malachi and the New Testament?", "options": ["One thousand", "Four hundred", "One hundred", "Forty"]}, {"q": "Which empire spread the Greek language across the known world?", "options": ["Egypt", "Assyria", "Greece under Alexander the Great", "Babylon"]}, {"q": "Who is the messenger Isaiah and Malachi promised in the New Testament?", "options": ["Peter", "Paul", "Stephen", "John the Baptist"]}, {"q": "What does Galatians 4:4 say about the timing of God's sending His Son?", "options": ["It happened by chance", "It happened before Abraham", "It happened when the fulness of the time was come", "It happened too late"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Between the Testaments and the Fullness of Time$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,3,2}'::int[], array[$j$About four hundred years passed with no new prophet.$j$,$j$Alexander's conquests spread the Greek language.$j$,$j$John the Baptist prepared the way for Jesus.$j$,$j$God sent forth His Son when the fulness of the time was come.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Between the Testaments and the Fullness of Time$j$ on conflict (item_id) do nothing;
